// A custom attribute is an ordinary class derived from Attribute
public class RouteAttribute : Attribute
{
    public RouteAttribute(string path) => Path = path;
    public string Path { get; }       // positional argument
    public int Order { get; set; }    // named argument
}

[Route("/orders", Order = 2)]   // the Attribute suffix is optional
public class OrdersController { }

